{
  "candidate_id": "candidate-6",
  "filepath": "lib/expression/node/ConstantNode.js",
  "changed_line": 139,
  "statement": "if (typeof value !== 'string' ||",
  "change_type": "A",
  "function_name": "validateNumericValue",
  "operation_type": "input_validation",
  "selection_reason": "Numeric value input -> type and regex validation -> prevents invalid numeric parsing",
  "security_relevance_score": 0.7,
  "code_context": "1: 'use strict';
2: 
3: var getType = require('../../utils/types').type;
4: var stringify = require('../../utils/string').stringify;
5: 
6: function factory (type, config, load, typed) {
7:   var register = load(require('./compile')).register;
8:   var compile = load(require('./compile')).compile;
9:   var Node = load(require('./Node'));
10: 
11:   /**
12:    * A ConstantNode holds a constant value like a number or string. A ConstantNode
13:    * stores a stringified version of the value and uses this to compile to
14:    * JavaScript.
15:    *
16:    * In case of a stringified number as input, this may be compiled to a BigNumber
17:    * when the math instance is configured for BigNumbers.
18:    *
19:    * Usage:
20:    *
21:    *     // stringified values with type
22:    *     new ConstantNode('2.3', 'number');
23:    *     new ConstantNode('true', 'boolean');
24:    *     new ConstantNode('hello', 'string');
25:    *
26:    *     // non-stringified values, type will be automatically detected
27:    *     new ConstantNode(2.3);
28:    *     new ConstantNode('hello');
29:    *
30:    * @param {string | number | boolean | null | undefined} value
31:    *                            When valueType is provided, value must contain
32:    *                            an uninterpreted string representing the value.
33:    *                            When valueType is undefined, value can be a
34:    *                            number, string, boolean, null, or undefined, and
35:    *                            the type will be determined automatically.
36:    * @param {string} [valueType]  The type of value. Choose from 'number', 'string',
37:    *                              'boolean', 'undefined', 'null'
38:    * @constructor ConstantNode
39:    * @extends {Node}
40:    */
41:   function ConstantNode(value, valueType) {
42:     if (!(this instanceof ConstantNode)) {
43:       throw new SyntaxError('Constructor must be called with the new operator');
44:     }
45: 
46:     if (valueType) {
47:       if (typeof valueType !== 'string') {
48:         throw new TypeError('String expected for parameter "valueType"');
49:       }
50:       if (typeof value !== 'string') {
51:         throw new TypeError('String expected for parameter "value"');
52:       }
53: 
54:       this.value = value;
55:       this.valueType = valueType;
56:     }
57:     else {
58:       // stringify the value and determine the type
59:       this.value = value + '';
60:       this.valueType = getType(value);
61:     }
62: 
63:     if (!SUPPORTED_TYPES[this.valueType]) {
64:       throw new TypeError('Unsupported type of value "' + this.valueType + '"');
65:     }
66:   }
67: 
68:   var SUPPORTED_TYPES = {
69:     'number': true,
70:     'string': true,
71:     'boolean': true,
72:     'undefined': true,
73:     'null': true
74:   };
75: 
76:   ConstantNode.prototype = new Node();
77: 
78:   ConstantNode.prototype.type = 'ConstantNode';
79: 
80:   ConstantNode.prototype.isConstantNode = true;
81: 
82:   /**
83:    * Compile the node to javascript code
84:    * @param {ConstantNode} node The node to be compiled
85:    * @param {Object} defs     Object which can be used to define functions
86:    *                          or constants globally available for the compiled
87:    *                          expression
88:    * @param {Object} args     Object with local function arguments, the key is
89:    *                          the name of the argument, and the value is `true`.
90:    *                          The object may not be mutated, but must be
91:    *                          extended instead.
92:    * @return {string} js
93:    * @private
94:    */
95:   function compileConstantNode(node, defs, args) {
96:     switch (node.valueType) {
97:       case 'number':
98:         if (config.number === 'BigNumber') {
99:           return 'math.bignumber(' + stringify(node.value) + ')';
100:         }
101:         else if (config.number === 'Fraction') {
102:           return 'math.fraction(' + stringify(node.value) + ')';
103:         }
104:         else {
105:           // remove leading zeros like '003.2' which are not allowed by JavaScript
106:           validateNumericValue(node.value);
107:           return node.value.replace(/^(0*)[0-9]/, function (match, zeros) {
108:             return match.substring(zeros.length);
109:           });
110:         }
111: 
112:       case 'string':
113:         // Important to escape unescaped double quotes in the string
114:         return stringify(node.value);
115: 
116:       case 'boolean':
117:         // prevent invalid values
118:         return String(node.value) === 'true' ? 'true' : 'false';
119: 
120:       case 'undefined':
121:         return 'undefined';
122: 
123:       case 'null':
124:         return 'null';
125: 
126:       default:
127:         // TODO: move this error to the constructor?
128:         throw new TypeError('Unsupported type of constant "' + node.valueType + '"');
129:     }
130:   }
131: 
132:   /**
133:    * Test whether value is a string containing a numeric value
134:    * @param {String} value
135:    * @return {boolean} Returns true when ok
136:    */
137:   function validateNumericValue (value) {
138:     // The following regexp is relatively permissive
139:     if (typeof value !== 'string' ||
140:         !/^[\-+]?((\d+\.?\d*)|(\d*\.?\d+))([eE][+\-]?\d+)?$/.test(value)) {
141:       throw new Error('Invalid numeric value "' + value + '"');
142:     }
143:   }
144: 
145:   // register the compile function
146:   register(ConstantNode.prototype.type, compileConstantNode);
147: 
148:   /**
149:    * Execute a callback for each of the child nodes of this node
150:    * @param {function(child: Node, path: string, parent: Node)} callback
151:    */
152:   ConstantNode.prototype.forEach = function (callback) {
153:     // nothing to do, we don't have childs
154:   };
155: 
156: 
157:   /**
158:    * Create a new ConstantNode having it's childs be the results of calling
159:    * the provided callback function for each of the childs of the original node.
160:    * @param {function(child: Node, path: string, parent: Node) : Node} callback
161:    * @returns {ConstantNode} Returns a clone of the node
162:    */
163:   ConstantNode.prototype.map = function (callback) {
164:     return this.clone();
165:   };
166: 
167:   /**
168:    * Create a clone of this node, a shallow copy
169:    * @return {ConstantNode}
170:    */
171:   ConstantNode.prototype.clone = function () {
172:     return new ConstantNode(this.value, this.valueType);
173:   };
174: 
175:   /**
176:    * Get string representation
177:    * @param {Object} options
178:    * @return {string} str
179:    */
180:   ConstantNode.prototype._toString = function (options) {
181:     switch (this.valueType) {
182:       case 'string':
183:         return stringify(this.value);
184: 
185:       default:
186:         return this.value;
187:     }
188:   };
189: 
190:   /**
191:    * Get LaTeX representation
192:    * @param {Object} options
193:    * @return {string} str
194:    */
195:   ConstantNode.prototype._toTex = function (options) {
196:     var value = this.value,
197:         index;
198:     switch (this.valueType) {
199:       case 'string':
200:         return '\\mathtt{' + stringify(value) + '}';
201: 
202:       case 'number':
203:         index = value.toLowerCase().indexOf('e');
204:         if (index !== -1) {
205:           return value.substring(0, index) + '\\cdot10^{' +
206:               value.substring(index + 1) + '}';
207:         }
208:         return value;
209: 
210:       default:
211:         return value;
212:     }
213:   };
214: 
215:   return ConstantNode;
216: }
217: 
218: exports.name = 'ConstantNode';
219: exports.path = 'expression.node';
220: exports.factory = factory;",
  "source_summary": "Numeric values come from user-provided mathematical expressions parsed by the expression parser. The parser creates ConstantNode instances with numeric values from tokens like '1446: return new ConstantNode(number, 'number');'",
  "sink_summary": "Validated numeric values are used in JavaScript code generation via compileConstantNode. When config.number is not BigNumber or Fraction, values are processed with regex and used directly in generated JavaScript code after removing leading zeros.",
  "guard_summary": "Type checking (typeof value !== 'string') and regex validation for numeric format. The validation prevents invalid numeric values from being compiled to JavaScript. This is a new guard added to validate numeric input before processing.",
  "risk_pattern": "User-provided numeric expressions are validated for proper format before being compiled to JavaScript code. Without validation, malformed numeric values could cause parsing errors or unexpected behavior in generated code.",
